let activeRoot;const mats=new Map();function mat(c){if(!mats.has(c))mats.set(c,new THREE.MeshStandardMaterial({color:c,roughness:.64}));return mats.get(c)}
function box(w,h,d,c,x,y,z,parent=activeRoot||scene){const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),mat(c));m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function ball(r,c,x,y,z,parent=activeRoot||scene,sx=1,sy=1,sz=1){const m=new THREE.Mesh(new THREE.SphereGeometry(r,20,14),mat(c));m.position.set(x,y,z);m.scale.set(sx,sy,sz);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function cylinder(r,h,c,x,y,z,parent=activeRoot||scene){const m=new THREE.Mesh(new THREE.CylinderGeometry(r,r,h,28),mat(c));m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function capsule(r,len,c,x,y,z,parent=activeRoot||scene){const m=new THREE.Mesh(new THREE.CapsuleGeometry(r,len,5,12),mat(c));m.position.set(x,y,z);m.castShadow=true;parent.add(m);return m}
function textSign(text,w,h,bg,fg='#ffffff'){const c=document.createElement('canvas');c.width=1024;c.height=256;const ctx=c.getContext('2d');ctx.fillStyle=bg;ctx.fillRect(0,0,1024,256);ctx.font='900 95px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillStyle=fg;ctx.fillText(text,512,138);const tex=new THREE.CanvasTexture(c);tex.colorSpace=THREE.SRGBColorSpace;return new THREE.Mesh(new THREE.PlaneGeometry(w,h),new THREE.MeshBasicMaterial({map:tex,side:THREE.DoubleSide}))}

let courseRoot,startSign,sweepers=[],bumpers=[],gates=[];
function buildCourse(){
 if(courseRoot){scene.remove(courseRoot);courseRoot.traverse(o=>{o.geometry?.dispose();if(o.material?.map){o.material.map.dispose();o.material.dispose()}})}
 courseRoot=new THREE.Group();scene.add(courseRoot);activeRoot=courseRoot;sweepers=[];bumpers=[];gates=[];configureLevel(level);
// The course is built entirely from original geometric assets.
for(const p of platforms){box(p.w,1.5,p.d,0xd77ac9,p.x,-1.05,p.z);box(p.w,.5,p.d,p.color,p.x,-.25,p.z);for(const x of [-1,1]){box(.18,.055,p.d,0xffffff,p.x+x*(p.w/2-.35),.035,p.z)}if(p.d>10){for(let z=p.z-p.d/2+2;z<p.z+p.d/2;z+=3){box(.5,.07,1.3,0xffffff,p.x,.045,z)}}}
// Start line, finish checkerboard, raised rails and flags.
for(let x=-10;x<=10;x+=1){for(let z=0;z<2;z++){box(1,.06,.7,(x+z)%2?0xffffff:0x375ba4,x,.08,7+z*.7)}}
for(let x=-10;x<=10;x++){for(let row=0;row<4;row++)box(1,.06,.75,(x+row)%2?0xffffff:0x3b3477,x,.08,-126-row*.75)}
for(const p of platforms.filter(p=>p.d>10)){const z=p.z,d=p.d-2;for(const x of [-p.w/2,p.w/2]){box(.4,.7,d,0xffd24d,x,.6,z);for(let zz=z-d/2;zz<=z+d/2;zz+=5){cylinder(.16,1.3,0xfff1d2,x,.3,zz)}}}
for(const x of [-9.6,9.6]){cylinder(.45,8,0xf762a0,x,4,-130);ball(.64,0xffd346,x,8,-130)}
const finish=textSign('FINISH!',18,3,'#f04c9a');finish.position.set(0,7.1,-130);activeRoot.add(finish);
for(const z of [4,-42,-99])for(const x of [-10,10]){cylinder(.12,4,0xffffff,x,2,z);const flag=new THREE.Mesh(new THREE.PlaneGeometry(2,1.2),mat(z===4?0xff5999:0xffd04d));flag.position.set(x+1,3.4,z);activeRoot.add(flag)}
startSign=textSign('GO GO GO!',11,1.8,'#624dc3');startSign.position.set(0,5.8,10);startSign.rotation.y=0;activeRoot.add(startSign);for(const x of [-6,6])cylinder(.2,6,0x7f6bd5,x,3,10);

for(const {x,z,r,speed} of getSweepers(level)){const group=new THREE.Group();group.position.set(x,0,z);activeRoot.add(group);cylinder(1,1.6,0xffc845,0,.8,0,group);cylinder(1.2,.2,0xffe781,0,1.6,0,group);const arm=new THREE.Group();arm.position.y=.8;group.add(arm);const bar=capsule(.37,r*2-.74,0xff579b,0,0,0,arm);bar.rotation.z=Math.PI/2;ball(.5,0xffe58e,-r,0,0,arm);ball(.5,0xffe58e,r,0,0,arm);sweepers.push({x,z,r,speed,arm,angle:x});}
for(const {x,z,phase} of getBumpers(level)){const group=new THREE.Group();group.position.set(x,0,z);activeRoot.add(group);cylinder(1.15,1.7,0xff68a9,0,.85,0,group);cylinder(1.25,.24,0xffde55,0,1.7,0,group);cylinder(1.25,.25,0xffe78a,0,.18,0,group);ball(.94,0xffa3cc,0,1.7,0,group,1,.35,1);bumpers.push({x,z,group,phase})}
for(const z of [-80,-90])for(const x of [-7,0,7]){const ring=new THREE.Mesh(new THREE.TorusGeometry(1.7,.12,8,32),mat(0xffe68d));ring.rotation.x=-Math.PI/2;ring.position.set(x,.06,z);activeRoot.add(ring)}

 for(const spec of levelById(level).gates){const g=new THREE.Group();g.position.set(0,0,spec.z);activeRoot.add(g);box(spec.w,1.5,.7,0xff609d,0,.75,0,g);for(let x=-spec.w/2+.5;x<spec.w/2;x+=1.5)box(.6,1.52,.73,0xffdf70,x,.75,0,g);gates.push({...spec,group:g})}
 activeRoot=null;scene.background.set(levelById(level).sky);scene.fog.color.set(levelById(level).sky);
}
buildCourse();
// Slime sea, floating islands and soft clouds.
const sea=box(700,.2,700,0xc5a2ed,0,-12,-70);sea.receiveShadow=false;
for(let i=0;i<45;i++){const x=(i%2?1:-1)*(36+Math.abs(Math.sin(i*27))*80),z=30-i*5;const g=new THREE.Group();g.position.set(x,12+(i%5)*5,z-30);for(let j=0;j<3;j++)ball(2.3,0xffffff,j*2,Math.sin(j)*.7,0,g,1.5,.55,1);scene.add(g)}
for(let i=0;i<18;i++){const x=(i%2?1:-1)*(21+i%4*12),z=15-i*9;cylinder(5+i%3,1.2,0x8acfd4,x,-5,z);cylinder(5+i%3,.4,0xb0edc5,x,-4.3,z);ball(1.5,0xf69dcc,x,-2.7,z,scene,.8,1.5,.8)}
const balloons=[];for(const [x,y,z,c] of [[19,14,-16,0xffdd68],[-23,17,-55,0xff91bd],[22,22,-100,0xa08af2]]){const g=new THREE.Group();g.position.set(x,y,z);ball(2.5,c,0,0,0,g,1,1.2,1);cylinder(.06,3,0xffffff,0,-4.1,0,g);box(1.3,.8,1.3,0xddab77,0,-5.7,0,g);scene.add(g);balloons.push(g)}

function makeBean(color){const g=new THREE.Group(),model=new THREE.Group();g.add(model);const bodyMat=new THREE.MeshStandardMaterial({color,roughness:.5});const body=new THREE.Mesh(new THREE.CapsuleGeometry(.62,.65,7,18),bodyMat);body.position.y=1.05;body.castShadow=true;model.add(body);ball(.5,0xfff7ee,0,1.25,-.535,model,1,.83,.27);for(const x of [-.17,.17])ball(.077,0x22273b,x,1.28,-.663,model,.7,1.65,.6);const arms=[];for(const x of [-.77,.77]){const arm=capsule(.19,.57,color,x,.98,0,model);arm.rotation.z=x>0?-.38:.38;arms.push(arm)}const feet=[];for(const x of [-.3,.3]){feet.push(ball(.25,color,x,.2,-.12,model,1,.65,1.4))}scene.add(g);return {g,model,bodyMat,arms,feet,x:0,z:0,y:0,vy:0,vx:0,vz:0,cp:0,hit:0,dive:0,finished:false,grounded:true,coyote:.1};}
let chosen=profile.get().color;const player=makeBean(chosen);const palette=[0x8660df,0xffc245,0x44ccba,0x4199f8,0xf98250,0xbb78df,0x91d457];const bots=Array.from({length:15},(_,i)=>({...makeBean(palette[i%palette.length]),isBot:true,speed:6.4+(i%6)*.16,lane:((i%3)-1)*7,seed:i*.9}));
const marker=textSign('YOU',1.7,.58,'#f04c9a');player.g.add(marker);marker.position.y=2.8;
const keys=new Set();let mode='lobby',previousMode='race',time=0,worldTime=0,count=0,countTime=0,qualified=0,falls=0,sound=profile.get().sound,toastTime=0,finishTime=0,lastJump=false,lastDive=false;let audioCtx;let jumpQueued=false,diveQueued=false;
function tone(freq=440,duration=.12,type='sine'){if(!sound)return;try{audioCtx??=new(window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')audioCtx.resume();const o=audioCtx.createOscillator(),gain=audioCtx.createGain();o.type=type;o.frequency.setValueAtTime(freq,audioCtx.currentTime);gain.gain.setValueAtTime(.07,audioCtx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(gain);gain.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration)}catch{}}
function toast(message){$('toast').textContent=message;toastTime=2.2;$('toast').style.opacity=1}
function resetBean(b,i){Object.assign(b,runnerState(i),{eliminated:false});b.g.visible=true;b.model.rotation.set(0,0,0);b.g.position.set(b.x,b.y,b.z)}
function resetAll(){resetBean(player,1);bots.forEach((b,i)=>{resetBean(b,i+2);b.g.visible=i<levelById(level).runners-1});time=0;falls=0;qualified=0;lastJump=false;lastDive=false;jumpQueued=false;diveQueued=false;$('qualified').textContent='0';$('checkpoint').textContent='Checkpoint 1 / 3';$('timer').textContent=formatTime(levelById(level).seconds);$('progress-fill').style.width='0%';$('progress-bean').style.left='0%';keys.clear()}
function formatTime(t){return `${Math.floor(Math.max(0,t)/60)}:${String(Math.floor(Math.max(0,t))%60).padStart(2,'0')}`}
function syncLevelUI(){const l=levelById(level);$('level-label').textContent=`LEVEL ${level} / 3`;$('race-name').textContent=l.name;$('qualify-limit').textContent=' / '+l.qualify;$('course-name').textContent=l.name;$('course-description').textContent=l.description;$('course-number').textContent=`0${level} / 03`;$('course-runners').textContent=l.runners;$('course-qualify').textContent=l.qualify;$('crowns').textContent=profile.get().crowns;$('guest-name').value=profile.get().name;
 $('level-picker').innerHTML=LEVELS.map(l=>`<button data-level="${l.id}" class="level-option ${l.id===level?'active':''}" ${l.id>profile.get().unlocked?'disabled':''}>${l.id>profile.get().unlocked?'🔒':'0'+l.id}<span>${l.name}</span></button>`).join('');document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>{level=Number(b.dataset.level);profile.update({selected:level});buildCourse();sea.material=mat(levelById(level).slime);resetAll();syncLevelUI()})}
function startRace(){disconnectOnline();if($('modal').open)$('modal').close();buildCourse();sea.material=mat(levelById(level).slime);resetAll();syncLevelUI();mode='countdown';count=3;countTime=0;$('lobby').hidden=true;$('hud').hidden=false;$('countdown').hidden=false;$('countdown').textContent='3';$('online-status').hidden=true;document.body.classList.add('racing');$('touch').hidden=!matchMedia('(pointer:coarse)').matches;tone(430)}
function lobby(){disconnectOnline();mode='lobby';$('modal').close();$('lobby').hidden=false;$('hud').hidden=true;$('touch').hidden=true;$('countdown').hidden=true;$('online-status').hidden=true;document.body.classList.remove('racing');resetAll();syncLevelUI()}
resetAll();
function pause(){if(online){keys.clear();jumpQueued=false;diveQueued=false;showModal('<h2>Online race is live</h2><p>The other runners keep moving while this menu is open.</p><button id=resume class=play-button>BACK TO RACE ➜</button><button id=quit class=secondary-button>Leave race</button>');$('resume').onclick=()=> $('modal').close();$('quit').onclick=lobby;return}if(!['race','countdown'].includes(mode))return;previousMode=mode;mode='paused';keys.clear();showModal('<div class="result-icon">Ⅱ</div><h2>Take a breather.</h2><p>Your beans aren’t going anywhere.</p><button class="play-button" id="resume">KEEP RUNNING ➜</button><button class="secondary-button" id="quit">Back to lobby</button>');$('resume').onclick=resume;$('quit').onclick=lobby}
function resume(){if(mode==='paused')mode=previousMode;$('modal').close()}
function showModal(html){$('modal-content').innerHTML=html;if(!$('modal').open)$('modal').showModal()}
function endRace(win){mode='results';finishTime=time;keys.clear();$('touch').hidden=true;profile.record(level,time,win);const best=profile.get().bests[level];const final=level===3;showModal(`<div class="result-icon">${win?'👑':'🫘'}</div><span class="pill">LEVEL ${level} · ${levelById(level).name.toUpperCase()}</span><h2>${win?(final?'Crown secured!':'Qualified!'):'A beautiful tumble.'}</h2><p>${win?(final?'Three levels. One champion. That’s you!':`Next up: Level ${level+1} — ${levelById(level+1).name}`):'Shake it off. Your unlocked levels are saved.'}</p><div class="result-stats"><div><b>${win?qualified+' / '+levelById(level).runners:'—'}</b><label>PLACEMENT</label></div><div><b>${time.toFixed(1)}s</b><label>RACE TIME</label></div><div><b>${falls}</b><label>TUMBLES</label></div></div>${best?`<p>Level best: <strong>${best.toFixed(1)}s</strong></p>`:''}<button class="play-button" id="again">${win&&!final?'LEVEL '+(level+1)+' — LET’S GO':'RACE AGAIN'} ➜</button><button class="secondary-button" id="back">Back to lobby</button>`);$('again').onclick=()=>{if(win&&!final)level++;else if(win&&final)level=1;profile.update({selected:level});introduceLevel()};$('back').onclick=lobby;if(win){tone(660,.2);setTimeout(()=>tone(880,.3),160);spawnConfetti()}else tone(180,.4)}
function introduceLevel(){const l=levelById(level);buildCourse();syncLevelUI();showModal(`<div class="result-icon">${level===3?'👑':'✦'}</div><span class="pill">${l.tag}</span><h2>Level ${level}</h2><h3>${l.name}</h3><p>${l.description}</p><p>${l.runners} runners · ${l.qualify} ${level===3?'winner':'qualify'}</p><button id="start-level" class="play-button">READY, BEAN? ➜</button>`);$('start-level').onclick=startRace}
const confetti=[];function spawnConfetti(){for(let i=0;i<100;i++){const m=box(.14,.08,.25,palette[i%palette.length],player.x+(Math.random()-.5)*10,player.y+3+Math.random()*8,player.z+(Math.random()-.5)*10);confetti.push({m,v:new THREE.Vector3((Math.random()-.5)*3,Math.random()*3,(Math.random()-.5)*3),life:5})}}

function animateBean(b,dt,moving=true){b.g.position.lerp(new THREE.Vector3(b.x,b.y,b.z),online?1-Math.exp(-dt*18):1);b.model.rotation.y=b.heading||0;b.model.rotation.x=THREE.MathUtils.lerp(b.model.rotation.x,b.dive>0?-1.3:0,Math.min(1,dt*12));b.model.rotation.z=b.hit>.5?Math.sin(worldTime*23)*.2:0;const stride=moving&&b.grounded?Math.sin(worldTime*15+b.z)*.5:0;b.arms[0].rotation.x=stride;b.arms[1].rotation.x=-stride;b.feet[0].position.y=.2+Math.max(0,stride)*.3;b.feet[1].position.y=.2+Math.max(0,-stride)*.3}
function updateBean(b,dt,dx,dz,jump,dive,isPlayer){const events=stepRunner(b,{dx,dz,jump,dive},dt,worldTime,level);if(isPlayer){falls=b.falls;if(events.includes('jump'))tone(540,.1);if(events.includes('hit')){tone(140,.16,'triangle');toast('Whoops! Keep on running.')}if(events.includes('fall'))toast('Back on your feet!');if(events.includes('checkpoint')){$('checkpoint').textContent=`Checkpoint ${b.cp+1} / 3`;toast('Checkpoint! Keep it moving ✦');tone(740,.14)}}if(events.includes('finish')){qualified++;$('qualified').textContent=String(qualified);if(isPlayer)endRace(qualified<=levelById(level).qualify);else{b.g.visible=false;if(qualified>=levelById(level).qualify&&mode==='race')endRace(false)}}animateBean(b,dt,Math.hypot(dx,dz)>.1)}

const camGoal=new THREE.Vector3(),lookGoal=new THREE.Vector3();let last=performance.now();
function frame(now){requestAnimationFrame(frame);const dt=Math.min((now-last)/1000,.04);last=now;if(online&&networkState)worldTime=networkState.clock;else if(!['paused','results'].includes(mode))worldTime+=dt;
  startSign.visible=mode==='lobby'&&innerWidth>700;const animateWorld=!['paused','results'].includes(mode);if(animateWorld){for(const s of sweepers){s.angle=worldTime*s.speed+s.x;s.arm.rotation.y=s.angle}for(const b of bumpers)b.group.position.x=bumperX(b,worldTime,level);for(const g of gates)g.group.position.x=gateX(g,worldTime);balloons.forEach((b,i)=>b.position.y+=Math.sin(worldTime+i)*dt*.3)}
  if(mode==='lobby'){const mobile=innerWidth<700;camGoal.set(mobile?24:35,mobile?30:33,mobile?30:37);lookGoal.set(mobile?-4:-9,0,mobile?-18:-31);for(const [i,b] of [player,...bots].entries()){b.g.visible=i<levelById(level).runners;b.g.position.set(b.x,Math.sin(worldTime*2+i)*.07,b.z);b.arms[0].rotation.z=-.3+Math.sin(worldTime*2+i)*.15;b.arms[1].rotation.z=.3-Math.sin(worldTime*2+i)*.15}camera.position.lerp(camGoal,.035);camera.lookAt(lookGoal)}
  else{const focus=online&&(player.finished||player.eliminated)?([...remoteBeans.values()].filter(b=>!b.finished&&!b.eliminated).sort((a,b)=>a.z-b.z)[0]||player):player;camGoal.set(focus.x*.45,Math.max(focus.y,0)+8.3,focus.z+13);lookGoal.set(focus.x*.6,Math.max(focus.y,0)+.6,focus.z-7);camera.position.lerp(camGoal,1-Math.exp(-dt*5));camera.lookAt(lookGoal);sun.position.set(player.x-25,55,player.z+20);sun.target.position.set(player.x,0,player.z-15)}
  marker.quaternion.copy(camera.quaternion);marker.position.y=2.85+Math.sin(worldTime*3)*.12;
  if(mode==='countdown'&&!online){countTime+=dt;if(countTime>=1){countTime-=1;count--;if(count>0){$('countdown').textContent=count;tone(430)}else{mode='race';$('countdown').textContent='GO!';tone(860,.25);setTimeout(()=>{$('countdown').hidden=true},700)}}}
  if(mode==='race'&&!online){
    time+=dt;const left=Math.max(0,levelById(level).seconds-Math.floor(time));$('timer').textContent=`${Math.floor(left/60)}:${String(left%60).padStart(2,'0')}`;
    let dx=(keys.has('KeyD')||keys.has('ArrowRight')?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')?1:0),dz=(keys.has('KeyS')||keys.has('ArrowDown')?1:0)-(keys.has('KeyW')||keys.has('ArrowUp')?1:0);const jump=keys.has('Space'),dive=keys.has('ShiftLeft')||keys.has('ShiftRight');updateBean(player,dt,dx,dz,(jump&&!lastJump)||jumpQueued,(dive&&!lastDive)||diveQueued,true);jumpQueued=false;diveQueued=false;lastJump=jump;lastDive=dive;
    if(mode==='race')for(const b of bots.slice(0,levelById(level).runners-1)){if(b.finished)continue;const input=botInput(b,worldTime,level);updateBean(b,dt,input.dx,input.dz,input.jump,input.dive,false);if(mode!=='race')break}
    const p=progress(player.z)*100;$('progress-fill').style.width=p+'%';$('progress-bean').style.left=p+'%';if(time>=levelById(level).seconds&&mode==='race')endRace(false);
  }
  if(online)onlineFrame(dt);
  if(toastTime>0&&mode!=='paused'){toastTime-=dt;if(toastTime<=0)$('toast').style.opacity=0}
  for(let i=confetti.length-1;i>=0;i--){const c=confetti[i];c.life-=dt;c.v.y-=dt*3;c.m.position.addScaledVector(c.v,dt);c.m.rotation.x+=dt*2;c.m.rotation.z+=dt*3;if(c.life<0){scene.remove(c.m);c.m.geometry.dispose();confetti.splice(i,1)}}
  renderer.render(scene,camera);
}
camera.position.set(35,33,37);camera.lookAt(-9,0,-31);requestAnimationFrame(frame);$('loading').hidden=true;
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)});
window.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','ShiftLeft','ShiftRight'].includes(e.code)&&['race','countdown'].includes(mode))e.preventDefault();if(e.code==='Escape'){e.preventDefault();if(mode==='paused')resume();else pause();return}if(!e.repeat&&mode==='race'){if(e.code==='Space')jumpQueued=true;if(e.code==='ShiftLeft'||e.code==='ShiftRight')diveQueued=true}keys.add(e.code)});window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>{keys.clear();pause()});document.addEventListener('visibilitychange',()=>{if(document.hidden)pause()});
$('play').onclick=()=>joinOnline();$('practice').onclick=introduceLevel;$('pause').onclick=pause;$('sound').onclick=()=>{sound=!sound;profile.update({sound});$('sound').textContent=sound?'♫':'♩';$('sound').style.opacity=sound?1:.5;$('sound').setAttribute('aria-label',sound?'Turn sound off':'Turn sound on');if(sound)tone()};
$('help').onclick=()=>{if(!online&&['race','countdown'].includes(mode)){previousMode=mode;mode='paused';keys.clear()}showModal('<div class="result-icon">✦</div><h2>Small bean. Big dreams.</h2><p>Qualify through three levels: 16 runners, then 8, then 4. Win the final to earn a crown. Jump the pink sweepers, dodge the bumpers, and leap between the golden platforms.</p><div class="help-grid"><div><kbd>W A S D / ARROWS</kbd>Move your bean</div><div><kbd>SPACE</kbd>Jump over hazards</div><div><kbd>SHIFT</kbd>Dive while airborne</div><div><kbd>ESC</kbd>Pause the race</div></div><p>Fall into the slime? You’ll return to your last flag checkpoint. On touch screens, use the on-screen controls.</p><button id="got-it" class="play-button">GOT IT ➜</button>');$('got-it').onclick=()=>{if(mode==='paused')resume();else $('modal').close()}};
$('credits').onclick=()=>showModal('<h2>The inspiration</h2><p>Bean Dash is an original browser fan game inspired by the colorful obstacle races of Fall Guys. Built with original geometric characters and course assets.</p><p>Reference research:<br><a href="https://www.youtube.com/watch?v=YT2G_DHxp_g" target="_blank" rel="noopener">Official Free for All gameplay trailer ↗</a><br><a href="https://www.mobygames.com/game/148912/fall-guys-ultimate-knockout/screenshots/" target="_blank" rel="noopener">Fall Guys screenshot gallery ↗</a></p><p>Live multiplayer with clearly labeled bots filling empty slots. Guest progress stays in this browser.<br>Not affiliated with Mediatonic or Epic Games.</p>');
$('close-modal').onclick=()=>{if(mode==='paused')resume();else if(mode==='results')lobby();else $('modal').close()};$('modal').addEventListener('cancel',e=>{e.preventDefault();if(mode==='paused')resume();else if(mode==='results')lobby();else $('modal').close()});
document.querySelectorAll('.swatch').forEach(btn=>btn.onclick=()=>{chosen=btn.dataset.color;profile.update({color:chosen});player.bodyMat.color.set(chosen);player.arms.forEach(m=>m.material=mat(chosen));player.feet.forEach(m=>m.material=mat(chosen));document.querySelectorAll('.swatch').forEach(b=>{b.classList.toggle('selected',b===btn);b.setAttribute('aria-pressed',String(b===btn))});tone(600,.05)});
document.querySelectorAll('[data-key]').forEach(btn=>{btn.addEventListener('pointerdown',e=>{e.preventDefault();btn.setPointerCapture(e.pointerId);keys.add(btn.dataset.key);if(btn.dataset.key==='Space')jumpQueued=true;if(btn.dataset.key==='ShiftLeft')diveQueued=true});for(const ev of ['pointerup','pointercancel','lostpointercapture'])btn.addEventListener(ev,()=>keys.delete(btn.dataset.key))});
// Read-only telemetry for browser smoke checks and accessibility tooling.
window.beanDash={getState:()=>({mode,time,qualified,falls,player:{x:player.x,y:player.y,z:player.z,checkpoint:player.cp},runners:levelById(level).runners,level,online,room:networkState?.room,phase:networkState?.phase,guest:profile.get().id})};

syncLevelUI();

const remoteBeans=new Map();
function escapeHTML(value){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function disconnectOnline(){online=false;clearTimeout(connectTimer);if(socket){socket.onclose=null;socket.close();socket=null}for(const b of remoteBeans.values()){scene.remove(b.g);b.g.traverse(o=>{o.geometry?.dispose();if(o.material&&!Array.from(mats.values()).includes(o.material)){o.material.map?.dispose();o.material.dispose()}})}remoteBeans.clear();networkState=null;myId=null;lastRound=-1;netRecorded.clear();$('level-intro').hidden=true}
function joinOnline(roomCode){disconnectOnline();level=1;buildCourse();resetAll();syncLevelUI();online=true;mode='waiting';$('lobby').hidden=true;$('hud').hidden=false;document.body.classList.add('racing');$('countdown').hidden=true;$('online-status').hidden=false;$('online-status').textContent='Connecting…';showModal('<div class="result-icon">🌐</div><h2>Finding your race…</h2><p>Connecting to the live race server.</p><button class="secondary-button" id="cancel-queue">Back to lobby</button>');$('cancel-queue').onclick=lobby;
 const proto=location.protocol==='https:'?'wss:':'ws:';socket=new WebSocket(`${proto}//${location.host}/ws`);const ws=socket;
 connectTimer=setTimeout(()=>{if(ws===socket&&ws.readyState!==WebSocket.OPEN)networkError('The race server is taking a little longer. Please try again.')},15000);
 ws.onopen=()=>{clearTimeout(connectTimer);const p=profile.get();ws.send(JSON.stringify({type:'join',name:p.name,color:p.color,room:roomCode||undefined}))};
 ws.onmessage=e=>{let data;try{data=JSON.parse(e.data)}catch{return}if(data.type==='error'){networkError(data.message);return}if(data.type==='joined'){myId=data.id;return}if(data.type==='state')receiveState(data)};
 ws.onerror=()=>networkError('Could not connect to the race server. Check your connection and retry.');ws.onclose=()=>{if(online)networkError('Connection lost. Your saved progress is safe. Join a new race to continue.')};
}
function networkError(message){disconnectOnline();mode='results';keys.clear();$('touch').hidden=true;showModal(`<h2>Race connection interrupted</h2><p>${escapeHTML(message)}</p><button id="retry-online" class="play-button">TRY AGAIN ➜</button><button id="back-online" class="secondary-button">Back to lobby</button>`);$('retry-online').onclick=()=>joinOnline();$('back-online').onclick=lobby}
function receiveState(s){if(!online)return;const previous=networkState;networkState=s;
 if(s.level!==level||s.round!==lastRound){level=s.level;lastRound=s.round;buildCourse();sea.material=mat(levelById(level).slime);syncLevelUI();keys.clear();jumpQueued=false;diveQueued=false;for(const b of remoteBeans.values())b.g.visible=false;if($('modal').open)$('modal').close()}
 const own=s.players.find(p=>p.id===myId);if(!own)return;
 bots.forEach(b=>b.g.visible=false);Object.assign(player,own);player.g.visible=!own.eliminated;time=s.time;falls=own.falls;qualified=s.qualified;
 for(const p of s.players){if(p.id===myId)continue;let b=remoteBeans.get(p.id);if(!b){b=makeBean(p.color);const label=textSign(p.isBot?'BOT':p.name,p.isBot?.8:2.5,p.isBot?.25:.45,p.isBot?'#6a7b96':'#386eb5');label.position.y=2.65;b.g.add(label);b.label=label;remoteBeans.set(p.id,b)}Object.assign(b,p);b.g.visible=!p.eliminated}
 $('qualified').textContent=s.qualified;$('timer').textContent=formatTime(s.remaining);$('checkpoint').textContent=own.eliminated?'Eliminated · spectating':own.finished?'Qualified · waiting for the field':`Checkpoint ${own.cp+1} / 3`;
 $('online-status').textContent=`LIVE · ${s.humans} HUMAN${s.humans===1?'':'S'} · ROOM ${s.room}`;
 const recordKey=s.room+':'+s.level;if(own.roundLevel===s.level&&!netRecorded.has(recordKey)&&(own.finished||(['intermission','complete'].includes(s.phase)&&own.eliminated))){profile.record(s.level,own.finishTime||s.time,own.finished&&own.rank<=s.qualify);netRecorded.add(recordKey)}
 mode=s.phase==='race'?'race':s.phase==='countdown'?'countdown':s.phase==='waiting'?'waiting':'online-results';
 $('touch').hidden=s.phase!=='race'||own.finished||own.eliminated||!matchMedia('(pointer:coarse)').matches;
 if(s.phase==='waiting'){
  if(previous?.phase!=='waiting'||!$('queue-count')){showModal('<div class="result-icon">🌐</div><span class="pill">LIVE MATCHMAKING</span><h2>Room <span id="room-code"></span></h2><p id="queue-count"></p><p>Invite friends now. Empty slots fill with labeled bots when the countdown ends.</p><button id="invite" class="play-button">COPY INVITE LINK ↗</button><button id="cancel-queue" class="secondary-button">Back to lobby</button>');$('room-code').textContent=s.room;$('invite').onclick=async()=>{const url=new URL(location.href);url.search='?room='+s.room;try{await navigator.clipboard.writeText(url.href);$('invite').textContent='LINK COPIED ✓'}catch{$('queue-count').textContent=url.href}};$('cancel-queue').onclick=lobby}
  $('queue-count').textContent=`${s.humans} player${s.humans===1?'':'s'} connected · Starts in ${Math.ceil(s.remaining)}s`;
 }
 $('countdown').hidden=s.phase!=='countdown';if(s.phase==='countdown')$('countdown').textContent=Math.max(1,Math.ceil(s.remaining));
 $('level-intro').hidden=s.phase!=='countdown';$('level-intro').textContent=`LEVEL ${s.level} · ${levelById(s.level).name}`;
 if(s.phase==='race'&&previous?.phase!=='race'){if($('modal').open)$('modal').close();tone(860,.2)}
 if(['intermission','complete'].includes(s.phase)){
  if(previous?.phase!==s.phase){const win=own.finished&&own.rank<=s.qualify;const finished=s.phase==='complete';const winner=s.players.find(p=>p.rank===1&&!p.eliminated);showModal(`<div class="result-icon">${win?'👑':'🫘'}</div><span class="pill">LEVEL ${s.level} COMPLETE</span><h2>${win?(finished?'You won the crown!':'Qualified!'):(finished?'Show complete':'Eliminated')}</h2><p>${finished?`${escapeHTML(winner?.name||'No runner')} ${winner?'wins the crown.':'qualified in time.'}`:win?`Next: Level ${s.level+1} — ${levelById(s.level+1).name}`:'Stay to watch the next round, or join a new show.'}</p><p id="next-round-timer"></p><div class="result-stats"><div><b>${own.rank||'—'}</b><label>PLACEMENT</label></div><div><b>${own.finishTime?own.finishTime.toFixed(1)+'s':'—'}</b><label>RACE TIME</label></div></div><button id="online-next" class="play-button">${finished?'NEW SHOW ➜':'WATCH THE COURSE'}</button><button id="online-exit" class="secondary-button">Back to lobby</button>`);$('online-next').onclick=finished?()=>joinOnline():()=> $('modal').close();$('online-exit').onclick=lobby;if(win){spawnConfetti();tone(660,.2)}}
  if($('next-round-timer'))$('next-round-timer').textContent=s.phase==='intermission'?`Level ${s.level+1} begins in ${Math.ceil(s.remaining)}s`:'Your personal progress has been saved in this browser.';
 }
}
function onlineFrame(dt){if(!networkState)return;animateBean(player,dt,mode==='race'&&!player.finished);for(const b of remoteBeans.values()){animateBean(b,dt,mode==='race'&&!b.finished);b.label?.quaternion.copy(camera.quaternion)}const p=progress(player.z)*100;$('progress-fill').style.width=p+'%';$('progress-bean').style.left=p+'%';netSent+=dt;if(netSent<.045||socket?.readyState!==WebSocket.OPEN)return;netSent=0;const controls=mode==='race'&&!$('modal').open&&!player.finished&&!player.eliminated;const dx=controls?Number(keys.has('KeyD')||keys.has('ArrowRight'))-Number(keys.has('KeyA')||keys.has('ArrowLeft')):0,dz=controls?Number(keys.has('KeyS')||keys.has('ArrowDown'))-Number(keys.has('KeyW')||keys.has('ArrowUp')):0;socket.send(JSON.stringify({type:'input',dx,dz,jump:controls&&jumpQueued,dive:controls&&diveQueued}));jumpQueued=false;diveQueued=false}
$('guest-name').addEventListener('change',()=>{profile.update({name:$('guest-name').value.trim()||'Guest Bean'});$('guest-name').value=profile.get().name});
$('privacy').onclick=()=>showModal(`<h2>Your own little bean.</h2><p>Your name, color, unlocked levels, crowns, and personal bests are saved only in this browser. Other browsers and devices have separate saves. Anyone using this same browser profile shares its save.</p><p>During a live race, other runners see your chosen name, color, and race position. The server never receives your saved progress. Race rooms are temporary.</p><p>${profile.isPersistent()?'Clearing browser data removes your progress.':'Browser storage is unavailable. Progress lasts for this visit only.'}</p><button id="clear-save" class="secondary-button">Reset this browser’s progress</button>`);
$('modal-content').addEventListener('click',e=>{if(e.target.id==='clear-save'){showModal('<h2>Reset your bean?</h2><p>This removes this browser’s levels, crowns, settings, and personal bests.</p><button id="confirm-reset" class="play-button">RESET MY PROGRESS</button><button id="cancel-reset" class="secondary-button">Keep my progress</button>');$('confirm-reset').onclick=()=>{profile.reset();location.href=location.pathname};$('cancel-reset').onclick=()=> $('modal').close()}});
for(const b of document.querySelectorAll('.swatch')){b.classList.toggle('selected',b.dataset.color===chosen);b.setAttribute('aria-pressed',String(b.dataset.color===chosen))}
const invitedRoom=new URLSearchParams(location.search).get('room');if(invitedRoom&&/^[A-Fa-f0-9]{6}$/.test(invitedRoom))joinOnline(invitedRoom);
